    public void testScoringWriteFailureKeepsUndoAndRetryAccurate() throws Exception {
        seed();final Store real=a.store;final Scoring[] score={null};
        ui(()->{JSONObject r=a.newRecord("matches");score[0]=new Scoring(r);score[0].point(true);score[0].point(true);a.saveRecord("matches",r);});
        File blocker=new File(a.getCacheDir(),"qa-unwritable-library-parent");try(FileOutputStream out=new FileOutputStream(blocker)){out.write(1);}
        Store failing=new Store(new android.content.ContextWrapper(a){@Override public File getFilesDir(){return blocker;}});failing.data=copy(real.data);
        for(int operation=0;operation<4;operation++){final int action=operation;ui(()->{a.store=failing;String before=score[0].match.toString();int history=score[0].history.length();assertFalse(a.saveScore(score[0],()->{switch(action){case 0:score[0].undo();break;case 1:score[0].point(false);break;case 2:score[0].startTie();break;default:score[0].finishEarly("Retired");}}));assertEquals(before,score[0].match.toString());assertEquals(history,score[0].history.length());assertFalse(score[0].complete());});getInstrumentation().sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);}
        ui(()->{a.store=real;assertTrue(a.saveScore(score[0],()->score[0].undo()));assertEquals(1,score[0].n("playerPoints"));assertEquals(1,score[0].history.length());});
        JSONObject saved=find(new Store(a).table("matches"),score[0].match.optString("id"));assertEquals(1,object(saved,"liveScore").optInt("playerPoints"));blocker.delete();
    }
    public void testExtendedScoringHistoryPersistsAndFullyUndoes() throws Exception {
        seed();final String[] match={null};ui(()->{JSONObject r=a.newRecord("matches");Scoring score=new Scoring(r);for(int i=0;i<1000;i++)score.point(i%2==0);assertFalse(score.complete());assertEquals("Deuce",score.points());assertEquals(1000,score.history.length());assertTrue(a.saveRecord("matches",r));match[0]=r.optString("id");});
        Store loaded=new Store(a);Scoring score=new Scoring(find(loaded.table("matches"),match[0]));for(int i=0;i<1000;i++)assertTrue(score.undo());assertFalse(score.undo());assertEquals(0,score.n("playerPoints"));assertEquals(0,score.n("opponentPoints"));assertEquals(0,score.history.length());loaded.saveRecord("matches",score.match);assertEquals(0,array(find(new Store(a).table("matches"),match[0]),"androidScoreHistory").length());
    }
