    public void testLargeMediaBackupRoundTripKeepsExactBytes() throws Exception {
        seed();JSONObject person=copy(a.store.player()),media=obj();put(media,"id",id());put(media,"fileName",media.optString("id")+".bin");put(media,"title","QA Large synthetic media");put(media,"description","Generated binary fixture for backup integrity testing");put(media,"mime","video/mp4");array(person,"androidMedia").put(media);ui(()->a.saveRecord("players",person));
        File source=MediaLibrary.file(a,media.optString("fileName")),archive=new File(a.getCacheDir(),"large-media-qa.zip");java.security.MessageDigest expected=java.security.MessageDigest.getInstance("SHA-256");byte[] block=new byte[65536];new Random(27).nextBytes(block);
        try{try(OutputStream stream=new FileOutputStream(source)){for(int i=0;i<800;i++){stream.write(block);expected.update(block);}}try(OutputStream stream=new FileOutputStream(archive)){BackupArchive.write(a,copy(a.store.data),stream);}BackupArchive.Staged stage;try(InputStream stream=new FileInputStream(archive)){stage=BackupArchive.read(a,stream);}try{File restored=new File(stage.directory,media.optString("fileName"));assertEquals(52_428_800L,restored.length());java.security.MessageDigest actual=java.security.MessageDigest.getInstance("SHA-256");try(InputStream stream=new FileInputStream(restored)){int n;while((n=stream.read(block))!=-1)actual.update(block,0,n);}assertTrue(Arrays.equals(expected.digest(),actual.digest()));}finally{BackupArchive.discard(stage.directory);}}finally{source.delete();archive.delete();}
    }
